import{_ as t,o as i,c as a,a3 as s,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/kataloge-schueler-spez-kursart-1.png",u="/bilder/unterricht-kataloge/kataloge-schueler-spez-kursart-2.png",f=JSON.parse('{"title":"Schülerspezifische Kursarten auswählen und sortieren","description":"","frontmatter":{"title":"Schülerspezifische Kursarten auswählen und sortieren","source_pageid":483,"source_revision":5451},"headers":[],"relativePath":"schild3/unterricht-kataloge/schuelerspezifische-kursarten-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/schuelerspezifische-kursarten-schulbezogene-kataloge.md"}'),o={name:"schild3/unterricht-kataloge/schuelerspezifische-kursarten-schulbezogene-kataloge.md"};function c(h,n,d,g,p,m){return i(),a("div",null,[...n[0]||(n[0]=[s('<h1 id="schulerspezifische-kursarten-auswahlen-und-sortieren" tabindex="-1">Schülerspezifische Kursarten auswählen und sortieren <a class="header-anchor" href="#schulerspezifische-kursarten-auswahlen-und-sortieren" aria-label="Permalink to &quot;Schülerspezifische Kursarten auswählen und sortieren&quot;">​</a></h1><p>Verwalten Sie die verfügbaren Kursarten für individuelle Fachbelegungen. Unterscheiden Sie die allgemeine Kursart eines Kurses von der Zuordnung beim einzelnen Schülerdatensatz.</p><p><a href="/bilder/unterricht-kataloge/kataloge-schueler-spez-kursart-1.png"><img src="'+l+'" alt="Die schülerspezifischen Kursarten." loading="lazy"></a></p><p><em>Die schülerspezifischen Kursarten.</em></p><p>Die schülerspezifischen Kursarten sind die Eintragungen, die bei den <em>&quot;Leistungsdaten&quot;</em> im <em>&quot;Akt. Habljahr&quot;&#39; zu den Fächern individuell als Kursarten gewählt werden können.</em></p><p>Verwenden Sie die für Schulform, Gliederung und Lernabschnitt vorgesehenen Kursarten. Die zulässigen Statistikschlüssel sind vorgegeben; schulinterne Kurzbezeichnungen ersetzen diese Zuordnung nicht.</p><p>Die Kursarten sind deshalb schülerspezifisch, weil es unter Umständen eine übergeordnete Kursart zum Kurs geben kann, die dann beim Schülerdatensatz nochmals unterschieden werden muss.</p>',7),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),r("Beispiel")]),e("p",null,[r("In der gymnasialen Oberstufe reicht zum Beispiel die allgemeine Kursart "),e("strong",null,"Grundkurs"),r(" nicht aus. Am Schülerdatensatz wird zwischen "),e("strong",null,"GKS"),r(" (Grundkurs schriftlich) und "),e("strong",null,"GKM"),r(" (Grundkurs mündlich) unterschieden. Leistungskurse werden als "),e("strong",null,"LK1"),r(" oder "),e("strong",null,"LK2"),r(", das dritte und vierte Abiturfach als "),e("strong",null,"AB3"),r(" beziehungsweise "),e("strong",null,"AB4"),r(" gekennzeichnet.")])],-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),r("Wichtig")]),e("p",null,"Bitte informieren Sie sich über das Schlüsselverzeichnis von IT.NRW zu den an Ihrer Schulform benötigten Kursarten!")],-1),s('<p><a href="/bilder/unterricht-kataloge/kataloge-schueler-spez-kursart-2.png"><img src="'+u+'" alt="Festlegen der Sortierung." loading="lazy"></a></p><p><em>Festlegen der Sortierung.</em></p><p>Die Kursarten können nach ihrem <em>internen Kürzel</em>, ihrer <em>Bezeichnung</em> oder <em>benutzerdefiniert</em> sortiert werden. Bei letzter Wahl ist wie üblich über die roten Pfeile links oder die Indizes rechts die Sortierreihenfolge festlegbar.</p><p>Benötigte Einträge werden über <strong>+</strong> aus den angebotenen Kursarten aufgenommen und mit <strong>-</strong> entfernt. Dabei werden keine neuen amtlichen Statistikschlüssel erfunden. Unter <em>&quot;Sichtbar</em>&quot; wird gesteuert, ob die Einträge im Katalog zwar vorhanden sind, aber in der Dropdown-Menü-Auswahl nicht angezeigt werden sollen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sch%C3%BClerspezifische_Kursarten_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5451.</p>',6)])])}const z=t(o,[["render",c]]);export{f as __pageData,z as default};
